select count(id)
from setmeal
where category_id = #{categoryId}

select s.*, c.name as categoryName from setmeal s left join category c on s.category_id = c.id
and s.name like concat('%', #{name,jdbcType=VARCHAR}, '%')
and s.status = #{status,jdbcType=INTEGER}
and s.category_id = #{categoryId,jdbcType=BIGINT}
order by s.create_time desc

select *
from setmeal


        and name like concat('%', #{name,jdbcType=VARCHAR}, '%')


        and category_id = #{categoryId,jdbcType=BIGINT}


        and status = #{status,jdbcType=INTEGER}
